using namespace ark;using V=arkjson::Value;
namespace {
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
void close(double a,double b,double tolerance,const char* message){if(std::abs(a-b)>tolerance)throw std::runtime_error(std::string(message)+": got "+std::to_string(a)+", expected "+std::to_string(b));}
V json(const char* text){V v;check(arkjson::parse(text,v),"test JSON parses");return v;}
V payload(const V& response){check(response.find("isError")&&!response.find("isError")->b,response.dump().c_str());return *response.find("structuredContent");}
V args(AgentSession& s,const char* commands){V q=V::makeObj();q.set("expected_revision",V::makeNum(s.revision));q.set("commands",json(commands));return q;}
void apply(AgentSession& s,const char* commands){(void)payload(s.call("doc_apply",args(s,commands)));}
void rejectedApply(AgentSession& s,V q,const char* substring){const auto before=documentToJson(s.document);const auto revision=s.revision;const auto response=s.call("doc_apply",q);check(response.find("isError")->b,"invalid retarget must reject");if(response.dump().find(substring)==std::string::npos)throw std::runtime_error(std::string("Retarget rejection expected '")+substring+"' for "+q.dump()+": "+response.dump());check(s.revision==revision&&documentToJson(s.document)==before,"rejected retarget preserves source, journal and revision");}
double extent(AgentSession& s,u64 id){for(const auto& body:s.document.evalBodies)if(body.id==id){const auto box=body.tessellate(s.document.tessOpt).computeBBox();return box.mx.x-box.mn.x;}throw std::runtime_error("evaluated retarget body missing");}
void retargetContracts(){
    AgentSession s;s.suppressFailureCapture();apply(s,R"([{"op":"feature.add","type":"box","name":"First","p":{"dx":"10","dy":"8","dz":"6"}},{"op":"feature.add","type":"box","name":"Second","p":{"dx":"25","dy":"8","dz":"6"}},{"op":"feature.add","type":"transform","name":"Moved","inputs":[1],"p":{"tx":"4"}},{"op":"feature.add","type":"box","name":"Later","p":{"dx":"40","dy":"8","dz":"6"}}])");
    close(extent(s,3),10,1e-6,"initial source drives transformed bounds");apply(s,R"([{"op":"feature.edit","id":"Moved","inputs":["Second"]}])");check(s.document.find(3)->inputs==std::vector<u64>{2},"retarget unique names bind stored dependency IDs");close(extent(s,3),25,1e-6,"retarget recomputes changed source bounds");
    auto missing=V::makeObj();missing.set("commands",json(R"([{"op":"feature.edit","id":3,"inputs":[1]}])"));rejectedApply(s,missing,"expected_revision");auto stale=args(s,R"([{"op":"feature.edit","id":3,"inputs":[1]}])");stale.set("expected_revision",V::makeNum(s.revision-1));rejectedApply(s,stale,"Revision conflict");
    rejectedApply(s,args(s,R"([{"op":"feature.edit","id":3,"inputs":[1,1]}])"),"repeat");rejectedApply(s,args(s,R"([{"op":"feature.edit","id":3,"inputs":[3]}])"),"edited feature");rejectedApply(s,args(s,R"([{"op":"feature.edit","id":3,"inputs":[4]}])"),"precede");rejectedApply(s,args(s,R"([{"op":"feature.edit","id":3,"inputs":[999]}])"),"");rejectedApply(s,args(s,R"([{"op":"feature.edit","id":3,"inputs":[1],"p":{"tx":"UnknownOffset"}}])"),"UnknownOffset");close(extent(s,3),25,1e-6,"failed recompute preserves evaluated publication");
    const auto saved=documentToJson(s.document);AgentSession reopened;std::string error;check(documentFromJson(saved,reopened.document,&error),error.c_str());reopened.revision=20;reopened.suppressFailureCapture();reopened.document.recompute();check(reopened.document.find(3)->inputs==std::vector<u64>{2},"retarget dependencies survive source persistence");close(extent(reopened,3),25,1e-6,"retarget result survives recompute after load");payload(reopened.call("doc_undo",V::makeObj()));check(reopened.document.find(3)->inputs==std::vector<u64>{1},"retarget undo survives journal reload");close(extent(reopened,3),10,1e-6,"journal undo republishes original bounds");payload(reopened.call("doc_redo",V::makeObj()));check(reopened.document.find(3)->inputs==std::vector<u64>{2},"retarget redo survives journal reload");close(extent(reopened,3),25,1e-6,"journal redo republishes retarget bounds");
}
void pageContracts(){
    const auto page=parseComponentSourcePage(R"HTML(<html><body><h1>Fixture manufacturer AX42</h1>
        <A HREF='../cad/./part.step?rev=2&amp;format=exact#download'> STEP <b>AX42</b> model </A>
        <a href="?view=download">Download options</a>
        <a href=/files/drawing.PDF>Dimension drawing</a>
        <a href='//cdn.example.test/model.igs'>IGES reference</a>
        <a href='../../spec/../datasheets/part.pdf'>Part datasheet</a>
        <a href='javascript:alert(1)'>Unsafe CAD command</a>
        <a href='http://example.test/insecure.step'>Insecure resource</a>
        <a href='#only-fragment'>Fragment</a>
        <!-- <a href='/hidden/comment.step'>Comment CAD</a> -->
        <SCRIPT>const injected="<a href='/hidden/script.step'>Executable CAD</a>";</SCRIPT>
        <style>.x:after{content:"<a href='/hidden/style.step'>Styled CAD</a>";}</style>
        <a href='/files/drawing.PDF'>Duplicate resource</a></body></html>)HTML","https://maker.example.test/old","https://maker.example.test/products/widgets/ax42?campaign=1");
    check(!page.find("javascript_executed")->b&&page.find("metadata_authority")->str.find("untrusted")!=std::string::npos,"page content remains untrusted data without execution");check(!page.find("links_truncated")->b,"bounded fixture links are complete");const auto& links=page.find("links")->arr;check(links.size()==5,"only distinct real HTTPS anchors are exposed");std::set<std::string> urls;for(const auto& link:links){urls.insert(link.find("url")->str);check(!link.find("retrieved")->b,"observed resource targets remain unfetched");}
    check(urls.count("https://maker.example.test/products/cad/part.step?rev=2&format=exact"),"relative dot segments, fragment removal and decoded query preserved");check(urls.count("https://maker.example.test/products/widgets/ax42?view=download"),"query relative URL resolves against final page path");check(urls.count("https://maker.example.test/files/drawing.PDF"),"unquoted root relative uppercase PDF preserved");check(urls.count("https://cdn.example.test/model.igs"),"protocol-relative resource uses HTTPS");check(urls.count("https://maker.example.test/datasheets/part.pdf"),"parent path segments resolve to host root");check(links.front().find("label")->str.find("AX42")!=std::string::npos&&links.front().find("kind")->str=="step","nested labels and uppercase anchor attributes parsed");check(page.find("resource_links")->arr.size()==5,"inferred resource kinds separate observed href evidence");
    bool rejected=false;try{parseComponentSourcePage("<html><script>window.location='/login';</script></html>","https://maker.example.test/a","https://maker.example.test/login");}catch(const std::exception&){rejected=true;}check(rejected,"script-only login content cannot establish readable evidence");
    const auto login=parseComponentSourcePage("<h1>Sign in to access CAD</h1><a href='/login'>Login</a>","https://maker.example.test/a","https://maker.example.test/login");check(login.find("metadata_authority")->str.find("untrusted")!=std::string::npos&&!login.find("links")->arr[0].find("retrieved")->b,"readable login link remains untrusted observed data, never supplier or geometry verification");
}
const V* toolSchema(const V& tools,const char* name){const V* rows=tools.find("tools");if(!rows&&tools.t==V::Arr)rows=&tools;if(!rows)return nullptr;for(const auto& tool:rows->arr)if(tool.find("name")->str==name)return tool.find("inputSchema");return nullptr;}
void extendedPageContracts(){
    auto fakeBase=parseComponentSourcePage(R"(<div data-example="<base href='https://wrong.example/cad/'>" data-note="<script>"></div><a href='part.step'>CAD</a>)","https://maker.example.test/catalog/a","https://maker.example.test/catalog/a");check(fakeBase.find("links")->arr.size()==1&&fakeBase.find("links")->arr[0].find("url")->str=="https://maker.example.test/catalog/part.step","Quoted example tags cannot create base elements or raw-text regions");
    auto parentBase=parseComponentSourcePage("<base href='https://vendor.example/catalog/sub/..'><a href='part.step'>STEP</a>","https://maker.example.test/a","https://maker.example.test/a");check(parentBase.find("links")->arr[0].find("url")->str=="https://vendor.example/catalog/part.step","Terminal parent path segment preserves directory base semantics");
    auto page=parseComponentSourcePage(R"(<title><a href='fake.step'>Text</a></title><script>const b="<base href='https://fake.test/'>";</script><base href='https://cdn.example.test/cad/'><textarea><a href='fake.step'>Example</a></textarea><a title='CAD > STEP' href='part.step'>Part</a><a href='part.step?compare=a>b'>Options</a>)","https://maker.example.test/a","https://maker.example.test/a");
    const auto& links=page.find("links")->arr;check(links.size()==2,"Only actual visible anchors survive raw-text filtering");check(links[0].find("url")->str=="https://cdn.example.test/cad/part.step","Real HTML base URL resolves relative CAD resource after quoted tag terminator");check(links[1].find("url")->str=="https://cdn.example.test/cad/part.step?compare=a>b","Quoted href terminators do not truncate observed URL");
    auto hostQuery=parseComponentSourcePage("<h1>Part</h1><a href='part.step'>STEP</a>","https://maker.example.test?campaign=1","https://maker.example.test?campaign=1");check(hostQuery.find("links")->arr[0].find("url")->str=="https://maker.example.test/part.step","Host-only page queries do not enter resolved resource authority");
}
void versionGateContracts(){
    Document doc;Feature base;base.type=FeatureType::NativeSolid;base.name="Base";base.nativeSpec=json(R"({"op":"box"})");base.p={{"width","20"},{"depth","20"},{"height","10"}};doc.addFeature(base);
    Feature finish;finish.type=FeatureType::NativeSolid;finish.name="Inferred asymmetric chamfer";finish.inputs={1};finish.nativeSpec=json(R"({"op":"chamfer","reference_face":"z_min","edges":["edge.x.ymin.zmin"]})");finish.p={{"distance","1"},{"distance2","2"}};doc.addFeature(finish);
    check(modeling031BNeedsVersion43(doc),"Inferred asymmetric chamfer cannot bypass new source version gate");auto source=json(documentToJson(doc,false,false).c_str());check(source.find("version")->num==43,"Implicit advanced chamfer saves source43");source.set("version",V::makeNum(42));Document destination;std::string error;check(!documentFromJson(source.dump(),destination,&error),"Relabelled inferred chamfer rejects old source version");
    doc.features.pop_back();Feature rib;rib.type=FeatureType::NativeSolid;rib.name="Retained legacy op key";rib.inputs={1};rib.nativeSpec=json(R"({"source_face":"z_max"})");rib.p={{"op","rib"},{"length","5"},{"thickness","1"},{"height","2"}};doc.addFeature(rib);check(modeling031BNeedsVersion43(doc),"Native solid p.op recipe uses same persistence gate as native.op");
    doc.features.back().nativeSpec.set("op",V::makeStr("box"));check(modeling031BNeedsVersion43(doc),"Source version follows evaluated p.op precedence when both operation keys exist");
}
void querySchemaContracts(){
    const auto tools=AgentSession::tools(true);const auto* schema=toolSchema(tools,"geometry_query");check(schema,"geometry_query discovery exists");const auto* props=schema->find("properties");check(props&&!props->find("filter"),"top-level geometry filter is absent from schema");check(schema->find("additionalProperties")&&!schema->find("additionalProperties")->b,"geometry schema explicitly rejects misplaced top-level fields");const auto* items=props->find("queries")->find("items");const auto* queryProps=items->find("properties");check(queryProps&&queryProps->find("filter"),"reference filter is typed within each query");const auto* filter=queryProps->find("filter");check(filter->find("type")->str=="object"&&filter->find("additionalProperties")&&!filter->find("additionalProperties")->b,"filter schema bounds known typed fields");const auto* fields=filter->find("properties");for(const char* name:{"kind","surface","normal","axis","radius_mm","near","within_mm","coaxial_origin","adjacent_to"})check(fields->find(name),"all documented reference filter fields are discoverable");check(fields->find("normal")->find("minItems")->num==3&&fields->find("normal")->find("maxItems")->num==3,"reference normal schema requires XYZ");
    AgentSession s;s.suppressFailureCapture();const auto before=documentToJson(s.document);const auto revision=s.revision;const auto bad=s.call("geometry_query",json(R"({"id":1,"filter":{"kind":"face"},"queries":[{"action":"references"}]})"));check(bad.find("isError")->b&&bad.dump().find("queries[].filter")!=std::string::npos,"runtime rejects misplaced top-level reference filter explicitly");check(s.revision==revision&&documentToJson(s.document)==before,"geometry query schema rejection is read-only");
#ifdef ARK_CONTRACTS_NATIVE_TESTS
    apply(s,R"([{"op":"feature.add","type":"native_solid","name":"Exact query fixture","native":{"op":"box"},"p":{"width":"20","depth":"30","height":"8"}}])");const auto readRevision=s.revision;const auto selected=payload(s.call("geometry_query",json(R"({"id":1,"queries":[{"action":"references","filter":{"kind":"face","normal":[0,0,1]},"unique":true}]})")));check(selected.find("results")->arr[0].find("ok")->b&&selected.find("results")->arr[0].find("count")->num==1&&s.revision==readRevision,"typed filter executes exact read-only unique selection");
    const auto full=payload(s.call("reference_inspect",json(R"({"id":1,"reference":"z_max"})")));const auto compact=payload(s.call("reference_inspect",json(R"({"id":1,"reference":"z_max","detail":"frame"})")));check(full.find("topology")&&!compact.find("topology")&&compact.dump().size()<full.dump().size(),"detail frame omits full exact topology inventory");check(compact.find("world_column_major")&&full.find("world_column_major")&&compact.find("world_column_major")->dump()==full.find("world_column_major")->dump(),"compact reference returns identical resolved exact frame");
#endif
}
Document assemblyFixture(){Document d;Feature f;f.type=FeatureType::Box;f.p={{"dx","2"},{"dy","3"},{"dz","4"}};d.addFeature(f);d.recompute();return d;}
AssemblyNode part(u64 id,bool fixed=false,u64 parent=0){AssemblyNode n;n.id=id;n.feature=1;n.parent=parent;n.fixed=fixed;n.name="Occurrence "+std::to_string(id);return n;}
AssemblyMate joint(u64 id,u64 a,u64 b,const char* type){AssemblyMate m;m.id=id;m.a=a;m.b=b;m.type=type;return m;}
const AssemblyPlacement& occurrence(const std::vector<AssemblyPlacement>& rows,u64 id){for(const auto& row:rows)if(row.node==id)return row;throw std::runtime_error("assembly occurrence missing");}
void followerPoleContracts(){
    for(const auto& type:{std::string("revolute"),std::string("prismatic")}){auto d=assemblyFixture();d.assembly={part(1,true),part(2),part(3)};d.assembly[1].p={{"rx","180"}};d.assembly[2].p={{"rx","180"}};d.mates={joint(1,2,3,"rigid"),joint(2,1,3,type.c_str())};
        std::vector<AssemblyPlacement> placements;AssemblyDiagnostics diagnostic;std::string error;check(resolveAssembly(d,placements,error,&diagnostic),error.c_str());check(diagnostic.freeDofs==1&&diagnostic.eliminatedRigidBodies==1,"Eliminated follower joint recovers antiparallel pole with one independent DOF");check(occurrence(placements,3).world.transformDir({0,0,1}).approx({0,0,1},1e-6),"Condensed follower axis aligns at actual joint endpoint");}
}
void assemblyContracts(){
    std::vector<AssemblyPlacement> placements;AssemblyDiagnostics diagnostic;std::string error;
    auto many=assemblyFixture();many.assembly.push_back(part(1,true));many.assembly[0].p={{"tx","10"},{"ty","20"},{"tz","30"}};for(u64 i=2;i<=96;++i){auto node=part(i);node.p={{"tx",std::to_string(i)},{"rz","137"}};many.assembly.push_back(node);many.mates.push_back(joint(i-1,1,i,"rigid"));}
    check(resolveAssembly(many,placements,error,&diagnostic),error.c_str());check(placements.size()==96&&diagnostic.solverMovingBodies==0&&diagnostic.eliminatedRigidBodies==95,"more than64 rigid attachments condense and preserve every physical occurrence");check(diagnostic.rank==570&&diagnostic.freeDofs==0&&diagnostic.rigidClusters.arr.size()==1,"anchored rigid cluster reports full eliminated rank and zero free motion");for(const auto& row:placements)check(row.world.transformPoint({0,0,0}).approx({10,20,30},1e-7)&&row.feature==1,"all condensed physical occurrences retain exact solved frame and shared definition");
    auto moving=assemblyFixture();moving.assembly.push_back(part(1,true));moving.assembly.push_back(part(2));moving.assembly[1].p={{"tx","15"},{"rz","31"}};moving.mates.push_back(joint(1,1,2,"revolute"));for(u64 i=3;i<=70;++i){moving.assembly.push_back(part(i));moving.mates.push_back(joint(i-1,2,i,"rigid"));}
    check(resolveAssembly(moving,placements,error,&diagnostic),error.c_str());check(placements.size()==70&&diagnostic.solverMovingBodies==1&&diagnostic.eliminatedRigidBodies==68,"moving rigid cluster leaves one numerical carrier and every occurrence");check(diagnostic.freeDofs==1&&diagnostic.rank==413,"revolute-grounded rigid cluster retains exactly axial rotation");for(u64 i=3;i<=70;++i)check(occurrence(placements,i).world.transformPoint({0,0,0}).approx(occurrence(placements,2).world.transformPoint({0,0,0}),1e-7),"moving cluster followers retain full-frame equality");
    auto conflict=assemblyFixture();conflict.assembly={part(1,true),part(2,true)};conflict.assembly[1].p={{"tx","10"}};conflict.mates.push_back(joint(1,1,2,"rigid"));check(!resolveAssembly(conflict,placements,error,&diagnostic)&&placements.empty(),"conflicting fixed anchors reject without dropping occurrence constraints");
    auto loop=assemblyFixture();loop.assembly={part(1,true),part(2),part(3)};loop.mates={joint(1,1,2,"rigid"),joint(2,2,3,"rigid"),joint(3,3,1,"rigid")};loop.mates[2].reference_a="X";loop.mates[2].reference_b="Z";check(!resolveAssembly(loop,placements,error,&diagnostic)&&placements.empty(),"inconsistent rigid loop rejects without absorbing error in condensed frames");
    auto carriers=assemblyFixture();AssemblyNode ground;ground.id=100;ground.name="Ground group";AssemblyNode carrier;carrier.id=200;carrier.name="Cross-parent carrier";carriers.assembly={ground,carrier,part(1,true,100),part(2,false,200),part(3,false,200)};carriers.assembly[3].p={{"tx","9"}};carriers.mates={joint(1,1,2,"revolute"),joint(2,2,3,"rigid")};check(resolveAssembly(carriers,placements,error,&diagnostic),error.c_str());check(placements.size()==3&&diagnostic.eliminatedRigidBodies==0&&diagnostic.rigidClusters.arr.empty(),"cross-parent group carriers are excluded from independent rigid condensation");check(occurrence(placements,2).world.transformPoint({0,0,0}).approx(occurrence(placements,3).world.transformPoint({0,0,0}),1e-5),"cross-parent solver still enforces internal rigid equality");
}
}
int main(){try{retargetContracts();pageContracts();extendedPageContracts();versionGateContracts();querySchemaContracts();assemblyContracts();followerPoleContracts();std::cout<<"031B contracts: input retarget/journal/atomicity, observed resource hrefs, typed geometry queries and rigid-carrier condensation passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
